#define CHECK(x) do { if (!(x)) { fprintf(stderr,"failed %s:%d: %s\n",__FILE__,__LINE__,#x); return 1; } } while (0)
#define SECTOR 2352u
#define BIG_LBA 21u
#define BIG_EXTENT 0x6000u
#define BIG_COUNT 300u
static void W16(uint8_t *p,uint16_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);} static void W32(uint8_t *p,uint32_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);p[2]=(uint8_t)(v>>16);p[3]=(uint8_t)(v>>24);}
static uint8_t *User(uint8_t *d,unsigned lba){return d+(size_t)lba*SECTOR+24;}
static uint8_t *BigByte(uint8_t *d,size_t off){return User(d,BIG_LBA+(unsigned)(off/2048u))+off%2048u;}
static void BigW32(uint8_t *d,size_t off,uint32_t v){uint8_t b[4];W32(b,v);for(unsigned i=0;i<4;i++)*BigByte(d,off+i)=b[i];}
static void Headers(uint8_t *d,size_t n){for(size_t i=0;i<n/SECTOR;i++){uint8_t *p=d+i*SECTOR;p[0]=0;memset(p+1,0xff,10);p[11]=0;p[15]=2;}}
static void Hash(const uint8_t *p,size_t n,uint8_t d[32]){struct NativeSha256 h;NativeSha256_Init(&h);NativeSha256_Update(&h,p,n);NativeSha256_Final(&h,d);}
static void Entry(uint8_t *d,unsigned i,unsigned off,unsigned size){BigW32(d,8u+i*8u,off);BigW32(d,12u+i*8u,size);}
/* Synthetic-only corpus. BIGFILE has a 0x6000-byte ISO extent while the
 * 300-entry table crosses a user sector. LOD1 is one DRAM envelope; base+2
 * is deliberately poisoned VRAM and must never be interpreted as a map. */
static void Build(uint8_t *d,size_t n){uint8_t *p,*lod1,*vram;memset(d,0,n);Headers(d,n);p=User(d,16);p[0]=1;memcpy(p+1,"CD001",5);p[6]=1;W32(p+158,20);W32(p+166,2048);p=User(d,20);p[0]=47;W32(p+2,BIG_LBA);W32(p+10,BIG_EXTENT);p[25]=0;p[32]=13;memcpy(p+33,"BIGFILE.BIG;1",13);BigW32(d,4,BIG_COUNT);Entry(d,1,9,0x304);Entry(d,2,10,16);lod1=User(d,30);W32(lod1,0x280);lod1+=4;W32(lod1+0,0x1c0);W32(lod1+0x148,1);W32(lod1+0x14c,0x240);W32(lod1+0x188,0x260);W32(lod1+0x1c0,1);W32(lod1+0x1cc,0x1e0);lod1[0x1e0+0x3e]=0;W16(lod1+0x240+8,0xffff);W16(lod1+0x240+9,0xffff);W16(lod1+0x240+10,0xffff);W16(lod1+0x240+11,0xffff);W32(lod1+0x260,0x270);W16(lod1+0x270,(uint16_t)-0x1303);W16(lod1+0x272,1);W32(lod1+0x280,20);W32(lod1+0x284,0);W32(lod1+0x288,0x14c);W32(lod1+0x28c,0x188);W32(lod1+0x290,0x1cc);W32(lod1+0x294,0x260);vram=User(d,31);memset(vram,0xa5,16);}
int main(void){uint8_t disc[40*SECTOR],hash[32],json[16384],before[16384];static const char jsonPrefix[]={"{\"version\":1,\"corpus\":25,\"stored\":1,\"lod1Addressable\":1,\"excludedStoredEntryCount\":1,"};struct NativeTopologyAssetCensus c;size_t n1,n2;Build(disc,sizeof(disc));Hash(disc,sizeof(disc),hash);CHECK(NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c));CHECK(c.corpusCount==25&&c.storedCount==1&&c.lod1AddressableCount==1&&c.excludedStoredEntryCount==1);CHECK(c.records[0].restartAvailable&&c.records[0].navAvailableMask==1&&c.records[0].topology.levelID==0);CHECK(NativeTopologyAssetCensus_ToJson(&c,(char *)json,sizeof(json),&n1));CHECK(n1>=sizeof(jsonPrefix)-1&&!memcmp(json,jsonPrefix,sizeof(jsonPrefix)-1));CHECK(NativeTopologyAssetCensus_ToJson(&c,(char *)before,sizeof(before),&n2)&&n1==n2&&!memcmp(json,before,n1));CHECK(!NativeTopologyAssetCensus_ToJson(&c,(char *)before,n1-1,&n2));hash[0]^=1;CHECK(!NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c));hash[0]^=1;disc[16*SECTOR+1]=0;CHECK(!NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c));Build(disc,sizeof(disc));Hash(disc,sizeof(disc),hash);W32(User(disc,20)+10,0x800);CHECK(!NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c));Build(disc,sizeof(disc));Hash(disc,sizeof(disc),hash);Entry(disc,1,12,0x1001);CHECK(!NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c));Build(disc,sizeof(disc));Hash(disc,sizeof(disc),hash);Entry(disc,3,UINT32_MAX,1);CHECK(!NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c));Build(disc,sizeof(disc));W32(User(disc,30),UINT32_MAX);Hash(disc,sizeof(disc),hash);CHECK(NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c)&&c.records[0].stored&&!c.records[0].lod1Addressable);Build(disc,sizeof(disc));W32(User(disc,30),0x300);Hash(disc,sizeof(disc),hash);CHECK(NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c)&&!c.records[0].lod1Addressable);Build(disc,sizeof(disc));W32(User(disc,30)+4+0x280,0xfffffffcu);Hash(disc,sizeof(disc),hash);CHECK(NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c)&&!c.records[0].lod1Addressable);Build(disc,sizeof(disc));memset(User(disc,31),0xff,16);Hash(disc,sizeof(disc),hash);CHECK(NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c)&&c.records[0].lod1Addressable);return 0;}
